fault(0) // For Popular sort\n  authors       Json? // Array of strings\n  artists       Json? // Array of strings\n  publishers    Json? // Array of strings\n  rating        Float         @default(0)\n\n  chapters       Chapter[]\n  tags           ComicTag[]\n  folders        FolderComic[]\n  reviews        Review[]\n  libraryEntries LibraryEntry[]\n  posts          Post[]\n}\n\nenum PageMode {\n  STRIP // Vertical scroll (Webtoon)\n  PAGE // Horizontal pages (Manga)\n}\n\nmodel Chapter {\n  id          String   @id @default(uuid())\n  comicId     String\n  number      Float\n  title       String\n  slug        String\n  releaseDate DateTime\n  isLocked    Boolean  @default(false)\n  pageMode    PageMode @default(STRIP)\n  likes       Int      @default(0)\n\n  comic    Comic             @relation(fields: [comicId], references: [id])\n  pages    Page[]\n  comments Comment[]\n  progress ReadingProgress[]\n\n  @@unique([comicId, slug])\n}\n\nmodel Page {\n  id         String @id @default(uuid())\n  chapterId  String\n  orderIndex Int\n  imageUrl   String\n  width      Int\n  height     Int\n\n  chapter Chapter @relation(fields: [chapterId], references: [id])\n}\n\nmodel ReadingProgress {\n  userId           String\n  chapterId        String\n  pageNumber       Int\n  scrollPercentage Float\n  lastRead         DateTime @default(now())\n\n  user    User    @relation(fields: [userId], references: [id])\n  chapter Chapter @relation(fields: [chapterId], references: [id])\n\n  @@id([userId, chapterId])\n}\n\nmodel Tag {\n  id   Int    @id @default(autoincrement())\n  name String @unique\n  type String // Demographic/Theme\n\n  comics ComicTag[]\n}\n\nmodel ComicTag {\n  comicId String\n  tagId   Int\n\n  comic Comic @relation(fields: [comicId], references: [id])\n  tag   Tag   @relation(fields: [tagId], references: [id])\n\n  @@id([comicId, tagId])\n}\n\nmodel Post {\n  id        String   @id @default(uuid())\n  title     String\n  content   String?\n  flair     String? // e.g. \"Theory\", \"Art\", \"Discussion\"\n  comicId   String\n  userId    String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  comic    Comic     @relation(fields: [comicId], references: [id], onDelete: Cascade)\n  user     User      @relation(fields: [userId], references: [id])\n  comments Comment[]\n  votes    Vote[]\n}\n\nmodel Vote {\n  id        String   @id @default(uuid())\n  userId    String\n  value     Int // 1 for upvote, -1 for downvote\n  postId    String?\n  commentId String?\n  createdAt DateTime @default(now())\n\n  user    User     @relation(fields: [userId], references: [id])\n  post    Post?    @relation(fields: [postId], references: [id], onDelete: Cascade)\n  comment Comment? @relation(fields: [commentId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, postId])\n  @@unique([userId, commentId])\n}\n\nmodel Comment {\n  id        String   @id @default(uuid())\n  content   String\n  userId    String\n  chapterId String?\n  postId    String? // For community posts\n  parentId  String? // For nested replies\n  isSpoiler Boolean  @default(false)\n  isDeleted Boolean  @default(false)\n  isEdited  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user    User      @relation(fields: [userId], references: [id])\n  chapter Chapter?  @relation(fields: [chapterId], references: [id])\n  post    Post?     @relation(fields: [postId], references: [id])\n  parent  Comment?  @relation(\"CommentReplies\", fields: [parentId], references: [id])\n  replies Comment[] @relation(\"CommentReplies\")\n  votes   Vote[]\n}\n\nmodel Subscription {\n  id        String   @id @default(uuid())\n  userId    String\n  plan      String\n  startDate DateTime\n  endDate   DateTime\n\n  user User @relation(fields: [userId], references: [id])\n}\n\nmodel Folder {\n  id        String   @id @default(uuid())\n  userId    String\n  name      String\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n\n  // Sharing\n  isPublic Boolean @default(false)\n  shareId  String? @unique @default(uuid())\n\n  user   User          @relation(fields: [userId], references: [id])\n  comics FolderComic[]\n\n  @@unique([userId, name])\n}\n\nmodel FolderComic {\n  folderId String\n  comicId  String\n  addedAt  DateTime @default(now())\n\n  folder Folder @relation(fields: [folderId], references: [id], onDelete: Cascade)\n  comic  Comic  @relation(fields: [comicId], references: [id], onDelete: Cascade)\n\n  @@id([folderId, comicId])\n}\n\nmodel Review {\n  id        String   @id @default(uuid())\n  userId    String\n  comicId   String\n  recommend Boolean // Steam-style: thumbs up or down\n  comment   String? // Optional text review\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user      User             @relation(fields: [userId], references: [id])\n  comic     Comic            @relation(fields: [comicId], references: [id], onDelete: Cascade)\n  reactions ReviewReaction[]\n\n  @@unique([userId, comicId])\n}\n\nmodel ReviewReaction {\n  id        String   @id @default(uuid())\n  userId    String\n  reviewId  String\n  type      String // \"HELPFUL\", \"FUNNY\", \"👍\", etc.\n  createdAt DateTime @default(now())\n\n  user   User   @relation(fields: [userId], references: [id])\n  review Review @relation(fields: [reviewId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, reviewId, type])\n}\n\nmodel UserReadingStat {\n  id           String   @id @default(uuid())\n  userId       String\n  date         DateTime @db.Date\n  chaptersRead Int      @default(0)\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@unique([userId, date])\n}\n\nenum LibraryStatus {\n  READING\n  COMPLETED\n  ON_HOLD\n  DROPPED\n  PLAN_TO_READ\n}\n\nmodel LibraryEntry {\n  userId     String\n  comicId    String\n  status     LibraryStatus\n  score      Float?\n  startedAt  DateTime?\n  finishedAt DateTime?\n  updatedAt  DateTime      @updatedAt\n\n  user  User  @relation(fields: [userId], references: [id])\n  comic Comic @relation(fields: [comicId], references: [id], onDelete: Cascade)\n\n  @@id([userId, comicId])\n}\n",
